package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class RecommendationItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long partnerId; private String actionTitle; @Column(length=1000) private String rationale; private Integer priorityRank; private Double confidence; private String status="PENDING"; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public String getActionTitle(){return actionTitle;} public void setActionTitle(String actionTitle){this.actionTitle=actionTitle;} public String getRationale(){return rationale;} public void setRationale(String rationale){this.rationale=rationale;} public Integer getPriorityRank(){return priorityRank;} public void setPriorityRank(Integer priorityRank){this.priorityRank=priorityRank;} public Double getConfidence(){return confidence;} public void setConfidence(Double confidence){this.confidence=confidence;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }